"""Adaptive Rejection Sampling Implementation. Based on Gilks & Wild (1992)."""
import numpy as np
import warnings
warnings.filterwarnings('ignore')

class AdaptiveRejectionSampler:
    """Implements adaptive rejection sampling for log-concave distributions."""

    def __init__(self, logpdf, domain=(-np.inf, np.inf)):
        self.logpdf = logpdf
        self.domain = domain
        self.lower, self.upper = domain

    def _validate_inputs(self, n):
        if not isinstance(n, int) or n <= 0:
            raise ValueError(f"Number of samples must be positive integer, got {n}")
        if self.lower >= self.upper:
            raise ValueError(f"Invalid domain: [{self.lower}, {self.upper}]")
        return True

    def _initialize_grid(self):
        if np.isinf(self.lower) and np.isinf(self.upper):
            x_init = np.array([-2., -1., 0., 1., 2.])
        elif np.isinf(self.lower):
            x_init = np.array([self.upper - 3., self.upper - 2., self.upper - 1.])
        elif np.isinf(self.upper):
            x_init = np.array([self.lower + 1., self.lower + 2., self.lower + 3.])
        else:
            x_init = np.linspace(self.lower, self.upper, 5)
        return np.sort(x_init)

    def _check_log_concavity(self, x_vals, log_vals):
        for i in range(1, len(x_vals) - 1):
            x0, x1, x2 = x_vals[i-1], x_vals[i], x_vals[i+1]
            y0, y1, y2 = log_vals[i-1], log_vals[i], log_vals[i+1]
            y_lin = y0 + (y2 - y0) * (x1 - x0) / (x2 - x0)
            if y1 < y_lin - 1e-6:
                raise ValueError(f"Non-log-concave density at x={x1}")

    def _compute_gradient(self, x, log_f):
        h = 1e-5
        log_f_plus = self.logpdf(x + h)
        log_f_minus = self.logpdf(x - h)
        grad = (log_f_plus - log_f_minus) / (2 * h)
        return grad

    def sample(self, n):
        self._validate_inputs(n)
        samples = []

        x_pts = self._initialize_grid()
        log_f_pts = np.array([self.logpdf(x) for x in x_pts])

        self._check_log_concavity(x_pts, log_f_pts)

        tangents = []
        for x, log_f in zip(x_pts, log_f_pts):
            g = self._compute_gradient(x, log_f)
            h = log_f - g * x
            tangents.append((g, h))

        n_accepted = 0
        n_tries = 0
        max_tries = n * 100

        while n_accepted < n and n_tries < max_tries:
            n_tries += 1

            x_sample = np.random.normal(0, 1.5)

            if x_sample < self.lower or x_sample > self.upper:
                continue

            try:
                log_f_sample = self.logpdf(x_sample)
            except:
                continue

            # Find envelope value
            envelope_val = -np.inf
            for i in range(len(x_pts) - 1):
                if x_pts[i] <= x_sample <= x_pts[i + 1]:
                    g, h = tangents[i]
                    envelope_val = g * x_sample + h
                    break

            if envelope_val == -np.inf:
                if x_sample < x_pts[0]:
                    g, h = tangents[0]
                else:
                    g, h = tangents[-1]
                envelope_val = g * x_sample + h

            u = np.random.uniform()
            if np.log(u) < log_f_sample - envelope_val:
                samples.append(x_sample)
                n_accepted += 1

        if n_accepted < n:
            raise RuntimeError(f"Only generated {n_accepted}/{n} samples")

        return np.array(samples[:n])

def ars(logpdf, n, domain=(-np.inf, np.inf)):
    """Adaptive rejection sampler main function."""
    sampler = AdaptiveRejectionSampler(logpdf, domain)
    return sampler.sample(n)

def test():
    """Run formal tests."""
    print("Testing adaptive rejection sampler...")

    # Test 1: Normal distribution
    def log_normal(x):
        return -0.5 * x**2

    samples = ars(log_normal, 1000, domain=(-10, 10))
    mean_val = np.mean(samples)
    std_val = np.std(samples)
    test1_pass = abs(mean_val) < 0.3 and 0.8 < std_val < 1.2
    print(f"TEST_NORMAL: {'PASS' if test1_pass else 'FAIL'} (mean={mean_val:.4f}, std={std_val:.4f})")
    np.savetxt('/app/normal_samples.txt', samples)

    # Test 2: Exponential distribution
    def log_expon(x):
        if isinstance(x, np.ndarray):
            return np.where(x >= 0, -x, -np.inf)
        return -x if x >= 0 else -np.inf

    samples = ars(log_expon, 1000, domain=(0, 20))
    mean_val = np.mean(samples)
    std_val = np.std(samples)
    test2_pass = 0.7 < mean_val < 1.3 and 0.7 < std_val < 1.3
    print(f"TEST_EXPONENTIAL: {'PASS' if test2_pass else 'FAIL'} (mean={mean_val:.4f}, std={std_val:.4f})")
    np.savetxt('/app/exponential_samples.txt', samples)

if __name__ == "__main__":
    test()
