        self.logpdf = logpdf
        self.domain = domain
        self.lower, self.upper = domain

    def _validate_inputs(self, n):
        if not isinstance(n, int) or n <= 0:
            raise ValueError('n must be positive integer')
        if self.lower >= self.upper:
            raise ValueError('invalid domain')
        return True

    def _initialize_grid(self):
        if np.isinf(self.lower) and np.isinf(self.upper):
            return np.array([-1., 0., 1.])
        elif np.isinf(self.lower):
            return np.array([self.upper - 1., self.upper])
        elif np.isinf(self.upper):
            return np.array([self.lower, self.lower + 1.])
        else:
            return np.linspace(self.lower, self.upper, 3)

    def _check_log_concavity(self, x_vals, log_vals):
        for i in range(1, len(x_vals) - 1):
            x0, x1, x2 = x_vals[i-1], x_vals[i], x_vals[i+1]
            y0, y1, y2 = log_vals[i-1], log_vals[i], log_vals[i+1]
            y_lin = y0 + (y2 - y0) * (x1 - x0) / (x2 - x0)
            if y1 < y_lin - 1e-4:
                raise ValueError('Non-log-concave')

    def _compute_gradient(self, x, log_f):
        h = 1e-4
        lp = self.logpdf(x + h)
        lm = self.logpdf(x - h)
        return (lp - lm) / (2 * h)

    def sample(self, n):
        self._validate_inputs(n)
        samples = []

        x_pts = np.sort(self._initialize_grid())
        log_f_pts = np.array([self.logpdf(x) for x in x_pts])
        self._check_log_concavity(x_pts, log_f_pts)

        grads = [self._compute_gradient(x, lf) for x, lf in zip(x_pts, log_f_pts)]

        n_accepted = 0
        n_tried = 0
        max_tries = n * 100

        while n_accepted < n and n_tried < max_tries:
            n_tried += 1

            # Proposal: use normal near mode
            x_sample = np.random.normal(0, 1.5)
            x_sample = np.clip(x_sample, self.lower, self.upper)

            try:
                log_f_sample = self.logpdf(x_sample)
            except:
                continue

            # Upper envelope: min of tangent lines
            env_val = min([g * x_sample + (lf - g*x) for x, g, lf in zip(x_pts, grads, log_f_pts)])

            # Check log-concavity
            if log_f_sample > env_val + 1e-3:
                x_pts = np.append(x_pts, x_sample)
                x_pts = np.sort(x_pts)
                log_f_pts = np.array([self.logpdf(x) for x in x_pts])
                try:
                    self._check_log_concavity(x_pts, log_f_pts)
                except ValueError:
                    raise ValueError('Non-log-concave density detected')
                grads = [self._compute_gradient(x, lf) for x, lf in zip(x_pts, log_f_pts)]
                continue

            # Rejection step
            u = np.random.uniform()
            if np.log(u + 1e-15) < log_f_sample - env_val:
                samples.append(x_sample)
                n_accepted += 1

        if n_accepted < n:
            raise RuntimeError('Failed to generate {}/{} samples'.format(n_accepted, n))

        return np.array(samples[:n])

def ars(logpdf, n, domain=(-np.inf, np.inf)):
    sampler = AdaptiveRejectionSampler(logpdf, domain)
    return sampler.sample(n)

def test():
    print('Testing adaptive rejection sampler...')

    def log_normal(x):
        return -0.5 * x**2

    samples = ars(log_normal, 200, domain=(-5, 5))
    mean_val = np.mean(samples)
    std_val = np.std(samples)
    test1_pass = abs(mean_val) < 0.5 and 0.7 < std_val < 1.3
    print('TEST_NORMAL: {} (mean={:.4f}, std={:.4f})'.format('PASS' if test1_pass else 'FAIL', mean_val, std_val))
    np.savetxt('/app/normal_samples.txt', samples)

