        if isinstance(x, np.ndarray):
            return np.where(x >= 0, -x, -np.inf)
        return -x if x >= 0 else -np.inf

    samples = ars(log_expon, 200, domain=(0, 8))
    mean_val = np.mean(samples)
    std_val = np.std(samples)
    test2_pass = 0.6 < mean_val < 1.4 and 0.6 < std_val < 1.4
    print('TEST_EXPONENTIAL: {} (mean={:.4f}, std={:.4f})'.format('PASS' if test2_pass else 'FAIL', mean_val, std_val))
    np.savetxt('/app/exponential_samples.txt', samples)

if __name__ == '__main__':
